#include <bits/stdc++.h>
using namespace std;

struct DSU {
    vector<int> parent, size;

    DSU(int n) : parent(n + 1), size(n + 1, 1) {
        iota(parent.begin(), parent.end(), 0);
    }

    int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }

    bool unite(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b) return false;
        if (size[a] < size[b]) swap(a, b);
        parent[b] = a;
        size[a] += size[b];
        return true;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M, K;
    cin >> N >> M >> K;

    vector<tuple<int, int, int>> edges(M);
    for (auto &[a, b, t] : edges) cin >> a >> b >> t;

    DSU dsu(N);

    for (auto [a, b, t] : edges) {
        if (t == 1 && !dsu.unite(a, b)) {
            cout << "N\n";
            return 0;
        }
    }

    int roadsToRemove = 0;
    for (auto [a, b, t] : edges) {
        if (t == 2 && !dsu.unite(a, b)) {
            ++roadsToRemove;
        }
    }

    cout << (roadsToRemove <= K ? "S\n" : "N\n");
    return 0;
}
